export * from "./api";
export * from "./conversation";
export * from "./flow";
export * from "./inspector";
export * from "./toast";

import type { RasaProError } from "./conversation";

export enum PlaceholderImage {
  NoFlow,
  Mobile,
  Cubes,
  CubesError,
  CubesPause,
}

/**
 * A single HTTP credential plus the transport that carries it. The two are
 * inseparable: which one a backend accepts is a property of the backend, and
 * sending both would leak the token into URLs and access logs.
 */
export type HttpAuth = {
  token: string;
  via: "header" | "query";
};

export type LogErrorHint = {
  tags?: { component: string; action: string };
  extra?: Record<string, string | null>;
};

export type LogErrorFn = (error: unknown, hint?: LogErrorHint) => void;

export type TrackFn = (event: string, properties?: Record<string, unknown>) => void | Promise<void>;

export type VoiceErrorHandler = ((err: RasaProError) => void) | null;

export type OnboardingTooltipTarget = "messageInput" | "inspectToggle";

export interface OnboardingTooltipConfig {
  target: OnboardingTooltipTarget;
  title: string;
  description: string;
  actionLabel: string;
  counter?: string;
  onAction: () => void;
  onDismiss: () => void;
}
